import{_ as i,o as a,c as n,ag as e}from"./chunks/framework.DEqXEGcv.js";const o=JSON.parse('{"title":"Signal Parent","description":"","frontmatter":{},"headers":[],"relativePath":"composition/signal-parent.md","filePath":"composition/signal-parent.md"}'),t={name:"composition/signal-parent.md"};function l(p,s,h,r,d,k){return a(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="signal-parent" tabindex="-1">Signal Parent <a class="header-anchor" href="#signal-parent" aria-label="Permalink to &quot;Signal Parent&quot;">​</a></h1><p><code>SIGNAL PARENT TO</code> allows a child instance to trigger a transition on its parent. This is the upward communication channel in a composition hierarchy -- children can tell the parent &quot;something happened, move to this state.&quot;</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><p>Inside a child machine&#39;s transition block:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">source </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  SIGNAL PARENT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> parent_state</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>When a child transition includes <code>SIGNAL PARENT TO</code>, the engine performs these steps in order:</p><ol><li>The child&#39;s transition completes (guards pass, mutations apply, state changes)</li><li>The engine looks up the child&#39;s <code>parent_id</code></li><li>The engine attempts to transition the parent to the specified state</li><li>If the parent&#39;s guards for that transition pass, the parent moves to the new state</li><li>If the parent&#39;s guards fail, the child&#39;s transition still succeeds -- the signal is best-effort on the parent side</li></ol><h2 id="example-shipment-delivers-an-order" tabindex="-1">Example: Shipment Delivers an Order <a class="header-anchor" href="#example-shipment-delivers-an-order" aria-label="Permalink to &quot;Example: Shipment Delivers an Order&quot;">​</a></h2><p>A Shipment signals its parent Order when delivery is confirmed:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE Shipment (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  PARENT : Order</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  DATA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    tracking : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPTIONAL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    carrier  : ENUM(fedex, ups, dhl, usps) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OPTIONAL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  STATES { created, dispatched, in_transit, delivered, lost }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  INITIAL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">STATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> created</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TERMINAL STATES { delivered, lost }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TRANSITIONS {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    created </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dispatched {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      GUARD  : tracking </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SET</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      GUARD  : carrier </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SET</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      ACTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : NOTIFY(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PARENT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">customer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;order.shipped&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    dispatched </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> in_transit {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    in_transit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> delivered {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      SIGNAL PARENT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> delivered</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    in_transit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lost {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">      ACTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : NOTIFY(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PARENT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">customer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shipment.lost&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>When the Shipment transitions from <code>in_transit</code> to <code>delivered</code>, the engine automatically transitions the parent Order to <code>delivered</code>. The Order must have a valid transition path to <code>delivered</code> from its current state (e.g., <code>shipped -&gt; delivered</code>).</p><h2 id="the-full-flow" tabindex="-1">The Full Flow <a class="header-anchor" href="#the-full-flow" aria-label="Permalink to &quot;The Full Flow&quot;">​</a></h2><p>Here is the sequence for the Order-Shipment example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Order:    paid -&gt; fulfilled     (spawns Shipment, guards on ALL items confirmed)</span></span>
<span class="line"><span>2. Shipment: created -&gt; dispatched (tracking and carrier set)</span></span>
<span class="line"><span>3. Order:    fulfilled -&gt; shipped  (guards on shipment.STATE IS dispatched)</span></span>
<span class="line"><span>4. Shipment: dispatched -&gt; in_transit</span></span>
<span class="line"><span>5. Shipment: in_transit -&gt; delivered  --&gt; SIGNAL PARENT TO delivered</span></span>
<span class="line"><span>6. Order:    shipped -&gt; delivered   (triggered by signal)</span></span></code></pre></div><p>Steps 5 and 6 happen atomically from the child&#39;s transition. The parent transition is triggered as part of the same operation.</p><h2 id="signal-and-guards" tabindex="-1">Signal and Guards <a class="header-anchor" href="#signal-and-guards" aria-label="Permalink to &quot;Signal and Guards&quot;">​</a></h2><p>The parent transition triggered by a signal still evaluates the parent&#39;s guards. If the parent defines guards on the target transition:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- In the Order machine</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">shipped </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> delivered {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  GUARD : ALL(items, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">STATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> confirmed)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The signal from the Shipment will attempt this transition. If the guard fails (perhaps a LineItem is not confirmed), the parent stays in its current state. The child transition still completes successfully.</p><h2 id="signal-does-not-carry-data" tabindex="-1">Signal Does Not Carry Data <a class="header-anchor" href="#signal-does-not-carry-data" aria-label="Permalink to &quot;Signal Does Not Carry Data&quot;">​</a></h2><p><code>SIGNAL PARENT TO</code> only specifies the target state. It does not pass data or an actor. The parent transition executes without an actor and without WITH data. Keep this in mind when designing guards -- the parent transition triggered by a signal should not require actor-based guards.</p><h2 id="multi-level-signals" tabindex="-1">Multi-Level Signals <a class="header-anchor" href="#multi-level-signals" aria-label="Permalink to &quot;Multi-Level Signals&quot;">​</a></h2><p>In a multi-level hierarchy (e.g., Pipeline &gt; Stage &gt; Job), a Job can signal its parent Stage, and the Stage can in turn signal its parent Pipeline. Each signal only reaches one level up -- there is no transitive signaling across levels. If you need a Job completion to affect the Pipeline, the Stage must have its own <code>SIGNAL PARENT TO</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Job signals Stage</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE Job (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  PARENT : Stage</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TRANSITIONS {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    running </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> completed {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      SIGNAL PARENT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> completed</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Stage signals Pipeline</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE Stage (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  PARENT : Pipeline</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TRANSITIONS {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    running </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> completed {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      GUARD : ALL(jobs, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">STATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> completed)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      SIGNAL PARENT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> completed</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>When the last Job completes, it signals the Stage. The Stage&#39;s guard checks that all Jobs are completed, and if so, the Stage transitions and signals the Pipeline.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Signals propagate one level at a time. Design each level to check its own children and decide whether to signal upward. This keeps the logic local and predictable.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If the parent has no valid transition from its current state to the signaled state, the signal is silently ignored. The child&#39;s transition still succeeds. Always verify that the parent machine defines the expected transition path.</p></div>`,28)])])}const g=i(t,[["render",l]]);export{o as __pageData,g as default};
